/* Inject the shared Family Support enhancement layer
 * (shared/family/family-support.css + .js) into the generated
 * lessons/<id>/family/ parent-support pages.
 *
 * Mirrors tools/inject-mobile-access.js: a single <link> before </head> and a
 * single <script defer> before </body>, each guarded by an idempotent sentinel
 * marker. The layer is additive and print-safe — see shared/family/.
 *
 * Scope: ONLY files matching lessons/<unit>-<lesson>/family/index.html. These
 * pages are regenerated by scripts/generate-lesson-support-pages.mjs, which
 * emits them without shared assets; re-run this injector after regenerating
 * (same contract as inject-mobile-access.js).
 *
 * Usage:
 *   node tools/inject-family-support.js            # inject (writes files)
 *   node tools/inject-family-support.js --dry-run  # report only
 *   node tools/inject-family-support.js --revert   # remove the injected blocks
 */
import { readdirSync, statSync, readFileSync, writeFileSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const LESSONS_DIR = join(ROOT, "lessons");

const MARK = "family-support-injected";
const LINK_TAG =
  '<link rel="stylesheet" href="/shared/family/family-support.css">';
const SCRIPT_TAG =
  '<script src="/shared/family/family-support.js" defer></script>';
const BEGIN_HEAD = `<!-- ${MARK}:begin (family support layer — tools/inject-family-support.js) -->`;
const END = `<!-- ${MARK}:end -->`;

const args = new Set(process.argv.slice(2));
const DRY = args.has("--dry-run");
const REVERT = args.has("--revert");

const report = {
  scanned: 0,
  injected: 0,
  already: 0,
  reverted: 0,
  skippedNoTags: [],
};

// Collect lessons/<id>/family/index.html only.
function familyPages() {
  const out = [];
  let entries = [];
  try {
    entries = readdirSync(LESSONS_DIR);
  } catch {
    return out;
  }
  for (const id of entries) {
    const file = join(LESSONS_DIR, id, "family", "index.html");
    let st;
    try {
      st = statSync(file);
    } catch {
      continue;
    }
    if (st.isFile()) out.push(file);
  }
  return out;
}

function revert(html) {
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const re = new RegExp(`\\s*${esc(BEGIN_HEAD)}[\\s\\S]*?${esc(END)}`, "g");
  return html.replace(re, "");
}

function processFile(file) {
  report.scanned++;
  let html = readFileSync(file, "utf8");

  if (REVERT) {
    if (html.includes(`${MARK}:begin`)) {
      if (!DRY) writeFileSync(file, revert(html));
      report.reverted++;
    }
    return;
  }

  if (html.includes(`${MARK}:begin`)) {
    report.already++;
    return;
  }
  if (!/<\/head>/i.test(html) || !/<\/body>/i.test(html)) {
    report.skippedNoTags.push(file);
    return;
  }

  html = html.replace(
    /<\/head>/i,
    `  ${BEGIN_HEAD}\n  ${LINK_TAG}\n  ${END}\n</head>`,
  );
  html = html.replace(
    /<\/body>/i,
    `  ${BEGIN_HEAD}\n  ${SCRIPT_TAG}\n  ${END}\n</body>`,
  );
  if (!DRY) writeFileSync(file, html);
  report.injected++;
}

const files = familyPages();
files.forEach(processFile);

console.log(
  `Family-support injection ${DRY ? "(dry-run)" : ""}${REVERT ? " — revert" : ""}`,
);
console.log("  family pages scanned:", report.scanned);
if (REVERT) {
  console.log("  reverted            :", report.reverted);
} else {
  console.log("  injected            :", report.injected);
  console.log("  already injected    :", report.already);
  console.log("  skipped (no tags)   :", report.skippedNoTags.length);
}
